	private void ensureSemanticsCurrent() {
		if (runtime.predicateRangeVersion() != predicateRangeVersion) {
			throw new IllegalStateException("detached refresh predicate-range semantics changed");
		}
		ensureAssumptionsCurrent(runtime.snapshotVersion());
	}

	/**
	 * The prepared source already embeds the rewrites made under {@link #assumptions}; replanning it is only sound
	 * while those assumptions hold for the data the refresh plans against.
	 */
	private void ensureAssumptionsCurrent(long dataRevision) {
		if (assumptions.committedSnapshotDependent() && dataRevision != buildDataRevision) {
			throw new IllegalStateException(
					"detached refresh committed-snapshot assumptions are stale: planned at data revision "
							+ buildDataRevision + ", store is at " + dataRevision);
		}
		if (assumptions.guaranteeDependent() && !buildRangeIdentity
				.equals(LmdbPipelinePlanCache.PredicateRangeIdentity.capture(buildRangeIdentity.predicates(),
						runtime))) {
			throw new IllegalStateException("detached refresh predicate-guarantee assumptions are stale");
		}
	}

	private static LmdbPlanDecisionCache.EstimatedCostInterval interval(
			PackedPlanDecisionSummary.CostInterval interval) {
		return new LmdbPlanDecisionCache.EstimatedCostInterval(interval.lower(), interval.upper());
	}

	private static Dataset dataset(LmdbPipelinePlanCache.DatasetIdentity identity) {
		return identity.toDataset();
	}

	static BindingSet bindings(LmdbPipelinePlanCache.BindingIdentity identity) {
		if (identity.values().isEmpty()) {
			return null;
		}
		MapBindingSet bindings = new MapBindingSet(identity.values().size());
		LmdbQueryValueIdentity.Materializer materializer = new LmdbQueryValueIdentity.Materializer();
		for (LmdbPipelinePlanCache.BoundValue value : identity.values()) {
			bindings.addBinding(value.name(), materializer.of(value.identity()));
		}
		return bindings;
	}

	private static long saturatedAdd(long left, long right) {
		return right > Long.MAX_VALUE - left ? Long.MAX_VALUE : left + right;
	}

	private static long retainedBytes(PackedPlanRefreshWork packedWork, List<IRI> predicates) {
		long retained = saturatedAdd(OBJECT_BYTES, packedWork.retainedBytes());
		for (IRI predicate : predicates) {
			retained = saturatedAdd(retained, 48L + 2L * predicate.stringValue().length());
		}
		return retained;
	}
